import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        a = []
        for _ in range(n):
            a.append(int(next(iterator)))
    except StopIteration:
        return

    target = sorted(a)

    if a == target:
        print(0)
        return

    pos_map = {}
    for i in range(n):
        val = a[i]
        if val not in pos_map:
            pos_map[val] = []
        pos_map[val].append(i)

    current_pos = {val: 0 for val in pos_map}

    pairs = []

    for i in range(n):
        if a[i] == target[i]:
            continue

        needed_val = target[i]

        j = i + 1
        while j < n and a[j] != needed_val:
            j += 1

        if j == n:
            print(-1)
            return

        if a[i] > a[j]:
            pairs.append((i + 1, j + 1))
            a[i], a[j] = a[j], a[i]
        else:
            print(-1)
            return

    print(len(pairs))
    for u, v in pairs:
        print(f"{u} {v}")

if __name__ == "__main__":
    solve()
